// task99: infer which crew_member_shifts columns are GENERATED by cross-checking stored values
import { createClient } from "@supabase/supabase-js";

const sb = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

const { data, error } = await sb
  .from("crew_member_shifts")
  .select("id, clock_in_time, clock_out_time, duration_minutes, hourly_rate, salary_amount")
  .order("clock_in_time", { ascending: false })
  .limit(300);

if (error) { console.error("err:", error.message); process.exit(1); }

let durExact = 0, durMismatch = 0, durNullOut = 0;
let salExact = 0, salMismatch = 0;
const mismatchSamples = [];

for (const r of data) {
  if (r.clock_out_time) {
    const mins = Math.round((new Date(r.clock_out_time) - new Date(r.clock_in_time)) / 60000);
    if (mins === r.duration_minutes) durExact++;
    else { durMismatch++; if (mismatchSamples.length < 5) mismatchSamples.push({ id: r.id, stored: r.duration_minutes, computed: mins }); }
  } else durNullOut++;

  const expect = Math.round((r.duration_minutes * Number(r.hourly_rate)) / 60);
  if (Math.round(Number(r.salary_amount)) === expect) salExact++;
  else { salMismatch++; if (mismatchSamples.length < 8) mismatchSamples.push({ id: r.id, dur: r.duration_minutes, rate: r.hourly_rate, sal: r.salary_amount, expect }); }
}

console.log(`rows=${data.length}`);
console.log(`duration vs (out-in): exact=${durExact} mismatch=${durMismatch} no-clockout=${durNullOut}`);
console.log(`salary vs dur*rate/60: exact=${salExact} mismatch=${salMismatch}`);
console.log("samples:", JSON.stringify(mismatchSamples, null, 2));
